package org.dromara.sports.tables.d13.complaint;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.common.core.enums.UserType;
import org.dromara.common.satoken.utils.LoginHelper;
import org.dromara.sports.api.GovernanceScopeApi;
import org.dromara.sports.api.OrganizationSessionApi;
import org.dromara.sports.api.OrganizationQualificationApi;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;

/** Account, organizer and coordinating government can see only complaints they are parties to. */
@Service @RequiredArgsConstructor
public class ComplaintService implements CapabilityProvider {
    private final ScopedJdbc db;private final ObjectMapper json;
    private final GovernanceScopeApi government;private final OrganizationSessionApi organizations;
    private final OrganizationQualificationApi qualifications;
    private static final Set<String> READS=Set.of("asp_complaint","asp_complaint_message","asp_event","asp_organization","asp_registration","asp_competition_unit","asp_registration_member","asp_account_tenant_principal","asp_governance_grant","asp_staff_grant");
    private static final Set<String> WRITES=Set.of("asp_complaint","asp_complaint_message","asp_notification","asp_event");
    public List<CapabilityDefinition> capabilities(){return List.of(
        capability(json,"complaint.submit","提交赛事问题","asp_complaint",true,true,Set.of("platform"),"",READS,WRITES,"objectType","objectId","message"),
        capability(json,"complaint.reply","回复问题处理","asp_complaint",true,false,Set.of("platform","organizer","government","admin"),"",READS,WRITES,"complaintId","message","expectedVersion"),
        capability(json,"complaint.handle","受理、协调或结案","asp_complaint",false,true,Set.of("organizer","government","admin"),"",READS,WRITES,"complaintId","action","message","expectedVersion"),
        capability(json,"complaint.reopen","对本人问题申请重新处理","asp_complaint",false,true,Set.of("platform"),"",READS,WRITES,"complaintId","message","expectedVersion"));}
    public JsonNode preview(String code,JsonNode in){return in.has("complaintId")?detail(id(in,"complaintId")):mine();}
    public JsonNode execute(String code,JsonNode in){
        if(code.equals("complaint.submit")){long a=account(),object=id(in,"objectId");String type=text(in,"objectType",32),message=text(in,"message",2000);var destination=destination(a,type,object);long complaint=nextId();var body=json.createObjectNode();body.put("message",message);db.update("INSERT INTO asp_complaint(id,tenant_id,applicant_account_id,object_type,object_id,request,evidence,status) VALUES (?,?,?,?,?,?::jsonb,'[]'::jsonb,'submitted')",complaint,destination.get("tenant_id"),a,type,object,body.toString());reopenEvent(type,object);append(complaint,"submitted",message);notify(complaint);return reference(json,"complaintId",complaint,"submitted");}
        long complaint=id(in,"complaintId");db.lock("complaint:"+complaint);var c=load(complaint);access(c);if(number(c.get("version"))!=in.path("expectedVersion").asLong(-1))throw fail("问题已被更新，请刷新后回复",409);String message=text(in,"message",2000),action="reply",state=c.get("status").toString();Long owner=c.get("owner_id")==null?null:number(c.get("owner_id"));
        if(code.equals("complaint.reopen")){if(LoginHelper.getUserType()!=UserType.PLATFORM_USER||number(c.get("applicant_account_id"))!=account()||!Set.of("resolved","rejected").contains(state))throw fail("只有本人已结案的问题可以重新申请处理",409);action="reopen";state="appealed";reopenEvent(c.get("object_type").toString(),number(c.get("object_id")));}
        if(code.equals("complaint.handle")){if(LoginHelper.getUserType()!=UserType.SYS_USER||TrustedRunContext.current()!=null)throw fail("处理结论请由责任岗位本人提交",403);action=text(in,"action",32);switch(action){case "accept"->state="accepted";case "coordinate"->state="investigating";case "resolve"->state="resolved";case "reject"->state="rejected";default->throw fail("请选择受理、协调或结案",400);}owner=LoginHelper.getUserId();}
        db.update("UPDATE asp_complaint SET status=?,owner_id=?,resolution=CASE WHEN ? IN ('resolve','reject') THEN ?::jsonb ELSE resolution END,version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",state,owner,action,"{\"message\":"+json.valueToTree(message)+"}",complaint);append(complaint,action,message);notify(complaint);return reference(json,"complaintId",complaint,state);
    }
    private void reopenEvent(String type,long object){if(type.equals("event"))db.update("UPDATE asp_event SET closure_status='wrap_up',version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=? AND closure_status='closed'",object);else if(type.equals("registration"))db.update("UPDATE asp_event SET closure_status='wrap_up',version=version+1,update_time=CURRENT_TIMESTAMP WHERE closure_status='closed' AND id IN(SELECT u.event_id FROM asp_registration r JOIN asp_competition_unit u ON u.id=r.unit_id WHERE r.id=?)",object);}
    private Map<String,Object> destination(long account,String type,long object){
        if(type.equals("registration")){var row=db.one("SELECT r.tenant_id,e.organization_id FROM asp_registration r JOIN asp_competition_unit u ON u.id=r.unit_id JOIN asp_event e ON e.id=u.event_id WHERE r.id=? AND (r.manager_account_id=? OR r.submitter_account_id=? OR EXISTS(SELECT 1 FROM asp_registration_member m WHERE m.registration_id=r.id AND m.account_id=?))",object,account,account,account);if(row!=null)return row;}
        if(type.equals("event")){var row=db.one("SELECT tenant_id,organization_id FROM asp_event WHERE id=? AND (publication_status='published' OR EXISTS(SELECT 1 FROM asp_competition_unit u JOIN asp_registration r ON r.unit_id=u.id JOIN asp_registration_member m ON m.registration_id=r.id WHERE u.event_id=asp_event.id AND m.account_id=?))",object,account);if(row!=null)return row;}
        if(type.equals("organization")){var row=db.one("SELECT tenant_id,id AS organization_id FROM asp_organization WHERE id=? AND status IN ('certified','restricted')",object);if(row!=null)return row;}
        throw fail("请选择本人相关报名、公开赛事或主办方",403);
    }
    private Map<String,Object> load(long complaint){var c=db.one("SELECT c.*,o.id AS organization_id FROM asp_complaint c JOIN asp_organization o ON o.tenant_id=c.tenant_id WHERE c.id=?",complaint);if(c==null)throw fail("问题不存在",404);return c;}
    private void access(Map<String,Object> c){var run=TrustedRunContext.current();if(run!=null){if("platform".equals(run.actorType())&&number(c.get("applicant_account_id"))==run.actorId())return;throw fail("智能体只可办理委托人本人的问题",403);}if(BusinessIdentity.getUserType()==UserType.PLATFORM_USER){if(number(c.get("applicant_account_id"))==account())return;throw fail("只能查看本人提交的问题",403);}if(LoginHelper.isSuperAdmin())return;long org=number(c.get("organization_id"));var managed=organizations.managedOrganization(BusinessIdentity.getUserId());if(managed.isPresent()&&managed.get().organizationId()==org&&qualifications.hasStaffAction(managed.get().tenantId(),org,managed.get().accountId(),"organize"))return;if(cn.dev33.satoken.stp.StpUtil.hasPermission("sports:government:complaint")&&government.allows(LoginHelper.getUserId(),org,"complaint"))return;throw fail("该问题不在你的处理范围",403);}
    public JsonNode detail(long complaint){var c=load(complaint);access(c);var out=json.createObjectNode();out.set("complaint",safeJson(json,c));out.set("messages",safeJson(json,db.list("SELECT actor_type,action,message,occurred_at FROM asp_complaint_message WHERE complaint_id=? ORDER BY occurred_at,id",complaint)));return out;}
    public JsonNode mine(){String where;Object[] args;if(BusinessIdentity.getUserType()==UserType.PLATFORM_USER){where="c.applicant_account_id=?";args=new Object[]{account()};}else if(LoginHelper.isSuperAdmin()){where="true";args=new Object[]{};}else{var org=organizations.managedOrganization(BusinessIdentity.getUserId());if(org.isPresent()){if(!qualifications.hasStaffAction(org.get().tenantId(),org.get().organizationId(),org.get().accountId(),"organize"))throw fail("当前组织岗位未获问题处理权限",403);where="c.tenant_id=?";args=new Object[]{org.get().tenantId()};}else{if(!cn.dev33.satoken.stp.StpUtil.hasPermission("sports:government:complaint"))throw fail("当前岗位未获投诉协调权限",403);where="EXISTS(SELECT 1 FROM asp_governance_grant g WHERE g.organization_id=o.id AND g.sys_user_id=? AND g.status='active' AND (g.valid_until IS NULL OR g.valid_until>CURRENT_TIMESTAMP) AND g.permissions @> '[\"complaint\"]'::jsonb)";args=new Object[]{LoginHelper.getUserId()};}}return safeJson(json,db.list("SELECT c.id,c.object_type,c.object_id,c.status,c.owner_id,c.version,c.create_time,c.request::text AS request,o.name AS organization_name FROM asp_complaint c JOIN asp_organization o ON o.tenant_id=c.tenant_id WHERE "+where+" ORDER BY c.update_time DESC LIMIT 100",args));}
    private void append(long id,String action,String message){var a=ActionContext.current();db.update("INSERT INTO asp_complaint_message(id,complaint_id,actor_type,actor_id,action,message,occurred_at) VALUES (?,?,?,?,?,?,CURRENT_TIMESTAMP)",nextId(),id,a.actorType(),a.actorId(),action,message);}
    private void notify(long complaint){var c=load(complaint);var recipients=new LinkedHashSet<Long>();recipients.add(number(c.get("applicant_account_id")));for(var a:db.list("SELECT account_id FROM asp_staff_grant WHERE organization_id=? AND status='active'",c.get("organization_id")))recipients.add(number(a.get("account_id")));for(long account:recipients){var content=json.createObjectNode();content.put("title","问题处理进度已更新");content.put("body","问题编号 "+complaint+"，请查看责任人回复和当前进度。");content.put("targetPath","/portal/issues/"+complaint);db.update("INSERT INTO asp_notification(id,tenant_id,recipient_account_id,business_type,business_id,business_revision,purpose,content,dedupe_key) VALUES (?,?,?,'complaint',?,?,'progress',?::jsonb,?)",nextId(),c.get("tenant_id"),account,complaint,c.get("version"),content.toString(),"complaint:"+complaint+":"+c.get("version"));}}
}
